const html=`<div class="td-milestone-layout"><div class="td-milestone-main"><div class="td-milestone-totals" id="milestone-totals"></div><div class="td-milestone-graph"><div class="td-milestone-legend"><b>2027 분기별 계획</b><span><i></i> 매출 <i></i> 매출총이익</span></div><div id="milestone-chart" role="img" aria-label="2027년 분기별 예상 매출과 매출총이익, 블록 유통사 공급량"></div></div></div><aside class="td-milestone-future"><span class="v-label">NEXT · 2028</span><h3>아시아<br>3개국 확장</h3><p>태국 · 베트남<br>인도네시아</p><div><b>탱고북 v2.0</b><span>다양한 블록</span></div><div id="milestone-future-totals"></div></aside></div><p class="td-note" id="milestone-status"></p><details class="v-evidence"><summary>계산 기준·미정 판매 계획</summary><p>유통사 공급량 기준이며 자사몰 주문·소비자 판매량은 합산하지 않습니다. 블록 패키지의 수량·정가·공급률·원가·플랫폼 비용과 연동됩니다. 탱고노트 판매는 모든 연도의 매출·매출총이익 전망에서 제외합니다. 매출총이익은 공급 매출에서 교구 원가와 플랫폼 운영비를 차감한 값이며 순이익이 아닙니다. 2028년 출시 분기·판매량과 신규 블록 가격은 미정입니다. 탱고노트는 2027년 3분기 출시, 소비자가 10만원 기준입니다.</p></details>`;
const css=`
.td-milestone-layout{display:grid;grid-template-columns:minmax(0,4fr) minmax(180px,1fr);gap:24px;margin-top:20px}
.td-milestone-main{min-width:0}.td-milestone-totals{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:0 0 20px}
.td-milestone-totals>div{padding:16px 20px;background:#edf5f0;border-top:3px solid #238f88}.td-milestone-totals>div:last-child{background:#fff1e8;border-color:#d77349}
.td-milestone-totals span,.td-milestone-totals small{display:block;font-size:13px;color:var(--doc-color-muted)}.td-milestone-totals strong{display:block;font-size:36px;margin:5px 0}
.td-milestone-graph{padding:16px 12px 0;background:white;border:1px solid var(--doc-color-line);border-radius:10px}
.td-milestone-legend{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:16px}.td-milestone-legend span{font-size:13px}.td-milestone-legend i{display:inline-block;width:20px;height:3px;vertical-align:middle;background:#238f88;margin:0 4px 0 12px}.td-milestone-legend i:last-child{background:#d77349}
#milestone-chart svg{width:100%;height:auto;display:block}
.td-milestone-future{padding:24px 20px;background:#f2f3ed;border-radius:10px}.td-milestone-future h3{font-size:28px;line-height:1.4;margin:16px 0}.td-milestone-future p{font-size:16px;line-height:1.8}.td-milestone-future>div{border-top:1px solid #ccd7cc;margin-top:24px;padding-top:20px}.td-milestone-future b,.td-milestone-future span{display:block}.td-milestone-future b{font-size:18px}.td-milestone-future div span{font-size:14px;margin-top:8px;color:var(--doc-color-muted)}
@media(max-width:699px){.td-milestone-layout{grid-template-columns:1fr}.td-milestone-totals{gap:10px}.td-milestone-totals>div{padding:12px}.td-milestone-totals strong{font-size:25px}.td-milestone-legend{flex-wrap:wrap}#milestone-chart{overflow:auto}#milestone-chart svg{min-width:600px}.td-milestone-future h3 br{display:none}}
`;module.exports={html,css};
